# Verify demo 2 diagonal clues and resulting cycle.
d2=[[0]*24 for _ in range(24)]
def put(r,c,v):
    if 0<=r<24 and 0<=c<24: d2[r][c]=v
for r in range(16): put(r,r+6,5); put(r,r+8,7)
for r in range(16,24): put(r,r-16,5)
for r in range(5,24): put(r,r-5,3)
for r in range(2): put(r,r+22,9)
o2=mod.transform(d2)
